{
  "correction_rules": [
    "Adjust forecasts downward if sentiment is neutral or negative (sentiment=0.00) and model shows persistent overestimation.",
    "Reduce forecast peak values after sharp upward spikes — model tends to overshoot and fail to correct quickly.",
    "Apply mean reversion bias: if 30-day forecast is > 10% above recent 18-day average, reduce by 5–10% unless sentiment strongly bullish.",
    "If sentiment is positive but forecast is still overestimating, apply a 3–5% downward correction to avoid overconfidence in short-term rallies.",
    "For horizon > 14 days, reduce forecast sensitivity to recent spikes — model overreacts to short-term volatility.",
    "If true outcome is consistently below forecast (especially in last 5–7 days), apply a 2–5% downward bias to avoid overfitting to recent highs."
  ]
}
